// friday13.cs — Friday the 13th experiments with the proleptic Gregorian calendar

// Find the earliest Friday the 13th starting from 0001-01-01
var date = new DateTime(1, 1, 13); // start checking the 13th of each month
DateTime? earliest = null;

while (date.Year == 1)
{
    if (date.DayOfWeek == DayOfWeek.Friday)
    {
        earliest = date;
        break;
    }
    date = date.AddMonths(1);
}

// If not found in year 1, keep going
if (earliest is null)
{
    date = new DateTime(2, 1, 13);
    while (earliest is null)
    {
        if (date.DayOfWeek == DayOfWeek.Friday)
            earliest = date;
        else
            date = date.AddMonths(1);
    }
}

Console.WriteLine($"Earliest Friday the 13th: {earliest:yyyy-MM-dd} ({earliest:dddd})");
Console.WriteLine();

// Count Friday the 13ths in a full 400-year cycle (the Gregorian calendar repeats every 400 years)
int count = 0;
var yearsByCount = new Dictionary<int, int>(); // year -> count in that year

for (int year = 1; year <= 400; year++)
{
    int yearCount = 0;
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateTime(year, month, 13);
        if (d.DayOfWeek == DayOfWeek.Friday)
        {
            yearCount++;
            count++;
        }
    }
    if (!yearsByCount.ContainsKey(yearCount))
        yearsByCount[yearCount] = 0;
    yearsByCount[yearCount]++;
}

Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");
Console.WriteLine($"Average per year: {count / 400.0:F4}");
Console.WriteLine();
Console.WriteLine("Distribution of Friday-the-13th counts per year:");
foreach (var kvp in yearsByCount.OrderBy(x => x.Key))
    Console.WriteLine($"  {kvp.Key} occurrence(s): {kvp.Value} years");

// Bonus: which day-of-week falls on the 13th most often?
Console.WriteLine();
Console.WriteLine("Day-of-week frequency for the 13th over 400 years:");
var dowCounts = new int[7];
for (int year = 1; year <= 400; year++)
    for (int month = 1; month <= 12; month++)
        dowCounts[(int)new DateTime(year, month, 13).DayOfWeek]++;

for (int i = 0; i < 7; i++)
    Console.WriteLine($"  {(DayOfWeek)i,-10}: {dowCounts[i]}");

